package io.github.diodeme.ji.agent.core;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import io.github.diodeme.ji.agent.AgentRuntimeBuilder;
import io.github.diodeme.ji.agent.SessionOptions;
import io.github.diodeme.ji.agent.ToolDefinition;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.ModelStreamEvent;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.extension.ToolExecutionPolicy;
import io.github.diodeme.ji.session.memory.MemorySessionStore;
import io.github.diodeme.ji.testkit.ScriptedModelProvider;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;

class SharedToolPolicyIntegrationTest {
    @Test
    void coreToolPathUsesConfiguredSharedPolicyAndRechecksBeforeEffect() {
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Tool("call-1", "echo", Map.of("value", "hello")),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.TOOL_USE)));
        AtomicInteger evaluations = new AtomicInteger();
        AtomicInteger effects = new AtomicInteger();
        ToolExecutionPolicy policy = context -> evaluations.incrementAndGet() == 1
                ? ToolExecutionPolicy.Evaluation.allow(false, "preflight")
                : ToolExecutionPolicy.Evaluation.deny("revoked");
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(new MemorySessionStore())
                .tool(ToolDefinition.sync("echo", "Echo", Map.of("type", "object"), (arguments, cancellation) -> {
                    effects.incrementAndGet();
                    return ToolDefinition.ToolResult.text("unexpected");
                }).alwaysAllow())
                .toolExecutionPolicy(policy).build()) {
            var session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
            var failure = org.junit.jupiter.api.Assertions.assertThrows(java.util.concurrent.CompletionException.class,
                    () -> session.prompt("hello").completion().toCompletableFuture().join());
            assertEquals("tool.policy_denied", ((io.github.diodeme.ji.error.JiException) failure.getCause())
                    .error().code().code());
            assertEquals(2, evaluations.get());
            assertEquals(0, effects.get());
            assertTrue(session.transcript().stream().noneMatch(message -> message.role() == io.github.diodeme.ji.ai.Message.Role.TOOL));
        }
    }

    @Test
    void policyDenialUsesStructuredFailure() {
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Tool("call-1", "echo", Map.of()),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.TOOL_USE)));
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(new MemorySessionStore())
                .tool(ToolDefinition.sync("echo", "Echo", Map.of("type", "object"),
                        (arguments, cancellation) -> ToolDefinition.ToolResult.text("unexpected")))
                .toolExecutionPolicy(context -> ToolExecutionPolicy.Evaluation.deny("host-policy"))
                .build()) {
            var session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
            var failure = org.junit.jupiter.api.Assertions.assertThrows(java.util.concurrent.CompletionException.class,
                    () -> session.prompt("hello").completion().toCompletableFuture().join());
            assertEquals("tool.policy_denied", ((io.github.diodeme.ji.error.JiException) failure.getCause())
                    .error().code().code());
        }
    }
}

